            StringBuilder sb = new StringBuilder();
            char c = readChar();
            while (!isPrintableChar(c)) {
                c = readChar();
            }
            do {
                sb.append(c);
                c = readChar();
            } while (isPrintableChar(c));
            return sb.toString();
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

