        private static boolean isNewLineChar(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

        public String next() {
            try {
                StringBuilder sb = new StringBuilder();
                int c = readByte();
                while (hasNextByte() && !isPrintableChar(c)) {
                    c = readByte();
                }
                if (c == -1) return null;
                do {
                    sb.append((char) c);
                    c = readByte();
                } while (hasNextByte() && isPrintableChar(c));
                return sb.toString();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        public long nextLong() {
            try {
                int c = readByte();
                while (hasNextByte() && !isPrintableChar(c)) {
                    c = readByte();
                }
                boolean minus = false;
                if (c == '-') {
                    minus = true;
                    c = readByte();
                }
                long res = 0;
                do {
                    res = res * 10 + (c - '0');
                    c = readByte();
                } while (hasNextByte() && isPrintableChar(c));
                return minus ? -res : res;
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }
